WITH base AS (SELECT id, order_id, method, amount, paid_at, status, DATE_TRUNC('WEEK', paid_at) AS paid_at_period, COALESCE(method, 'OTHER') AS method_filled FROM payments WHERE method = 'card') SELECT order_id, method, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, MIN(paid_at) AS first_seen, PERCENTILE_APPROX(amount, 0.5) AS amount_p50_2, ROUND(AVG(amount), 2) AS avg_amount, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, DENSE_RANK() OVER (PARTITION BY order_id ORDER BY PERCENTILE_APPROX(amount, 0.5) DESC) AS amount_p50_dense_rank FROM base GROUP BY 1, 2 ORDER BY amount_p50 NULLS LAST
